-- ============================================================================
-- payer-rules-nc-carecoord-absent.sql
--
-- Sixteen codes that North Carolina's Physician Services Fee Schedule does not
-- list. All five NC plans answered NOTHING for them: advance care planning,
-- chronic and principal care management, transitional care management, the
-- home-health certification G-codes and prolonged home E/M. A biller looking
-- any of them up for an NC Medicaid member got silence, which is
-- indistinguishable from "nobody checked".
--
-- HOW EACH ABSENCE WAS PROVED
-- By an adjacent-code bracket, not a failed search. The schedule lists 8,354
-- distinct codes; for every one of the sixteen the two codes that WOULD
-- surround it were located and shown to be consecutive:
--
--   99424-99427, 99439   99423 -> 99446
--   99490, 99491         99483 -> 99492
--   99495-99499          99494 -> A4263
--   G0179-G0181          G0127 -> G0248
--   G0318                G0315 -> G0328
--
-- A zero-hit search can mean "absent" or "my query was wrong". A populated
-- bracket can only mean absent. Note 99492/99493/99494 — psychiatric
-- collaborative care management — ARE listed and priced, which is why the
-- 99490 gap is a real editorial choice by NC rather than a missing block.
--
-- WHY 'unknown', AND WHY THE ANSWER IS CAREFUL ABOUT WHAT IT PROVES
-- NC's own fee-schedule portal states: "The inclusion of a rate within a fee
-- schedule does not guarantee that a service is covered." The converse is
-- equally true and is the limit of what this seed may claim — absence of a
-- RATE is not a coverage determination. NC's covered-code list is a separate
-- document, and it carries explicit "Not Covered" cells, so silence there
-- would also not be a denial.
--
-- So these rules say exactly this much: the fee schedule publishes no rate for
-- the code, and the plan therefore has no state rate to follow. They do not
-- say the service is non-covered. 'unknown' also keeps the codes out of the
-- picker, which is right — nothing here establishes them as billable.
--
-- SCOPE. These are NC Medicaid managed care plans (EBCI Tribal Option under
-- tribal_638), and the cited schedule is NC Medicaid fee-for-service. That is
-- the library's existing practice for NC — 159 covered rules per plan already
-- come from this same document — and the answers name the document plainly so
-- a biller can see the derivation rather than take it on trust.
-- ============================================================================

BEGIN;

UPDATE payer_rule pr
   SET expiration_date = GREATEST(pr.effective_date, DATE '2026-01-01')
 WHERE pr.expiration_date IS NULL
   AND pr.created_by <> 'extract:nc-carecoord-absent-2026-08'
   AND pr.state = 'NC' AND pr.attribute = 'covered'
   AND pr.code IN ('99424', '99425', '99426', '99427', '99439', '99490', '99491', '99495', '99496', '99497', '99498', '99499', 'G0179', 'G0180', 'G0181', 'G0318')
   AND pr.payer_id IN ('a0000000-0000-4000-8000-000000000103'::uuid, 'a0000000-0000-4000-8000-000000000104'::uuid, 'a0000000-0000-4000-8000-000000000105'::uuid, 'a0000000-0000-4000-8000-000000000101'::uuid, 'a0000000-0000-4000-8000-000000000102'::uuid);

ON CONFLICT (id) DO UPDATE SET
  value = EXCLUDED.value, coverage_status = EXCLUDED.coverage_status,
  product_line = EXCLUDED.product_line, confidence = EXCLUDED.confidence,
  source_quote = EXCLUDED.source_quote, effective_date = EXCLUDED.effective_date,
  expiration_date = NULL, source_doc_id = EXCLUDED.source_doc_id;

COMMIT;
