INSERT INTO payer_rule (id, payer_id, state, product_line, code, attribute, value, coverage_status, confidence, effective_date, expiration_date, source_doc_id, source_quote, created_by)
VALUES
  ('09a8c2f4-fd27-4b4e-83f2-c9d8b9c1476d'::uuid, 'a0000000-0000-4000-8000-000000000103'::uuid, 'NC', 'medicaid_mco', '99424', 'covered', '{"answer":"North Carolina Medicaid''s Physician Services Fee Schedule does not list 99424 (principal care management, first 30 minutes by a physician or other qualified health professional). It is absent, not denied: of the 8,354 codes the schedule carries, the two either side of it are consecutive — 99423 (Ol Dig E/M Svc 21+ Min) followed directly by 99446 (Ntrprof Ph1/Ntrnet/Ehr 5-10) — with no row in between. NC therefore publishes no rate for this code, so AmeriHealth Caritas North Carolina has no state rate to follow. Note that NC states separately that \"The inclusion of a rate within a fee schedule does not guarantee that a service is covered\", so the reverse also holds: this is an absent rate, not a coverage determination. Confirm with the plan before billing.","source":"NC Medicaid Physician Services Fee Schedule (Provider Specialty 001), read 2026-08-12"}'::jsonb, 'unknown', 0.7, DATE '2026-01-01', NULL, '826f207b-9dda-4c73-91e5-83b0090556a2'::uuid, 'NC Medicaid Physician Services Fee Schedule (Provider Specialty 001) — 99423 | 99446', 'extract:nc-carecoord-absent-2026-08'),
